package br.com.gestao.oficinas_api.ordem;
import br.com.gestao.oficinas_api.identidade.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.sql.Timestamp; import java.time.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ordens-servico/{orderId}/acesso") public class ServiceOrderAccessController {private final JdbcTemplate jdbc;private final ServiceOrderService orders;private final Clock clock;public ServiceOrderAccessController(JdbcTemplate j,ServiceOrderService o,Clock c){jdbc=j;orders=o;clock=c;}@PostMapping public Link create(Authentication a,@PathVariable UUID orderId){Identidade o=owner(a);orders.order(o,orderId);String token=UUID.randomUUID()+UUID.randomUUID().toString().replace("-","");try{String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));jdbc.update("INSERT INTO portal_link_os(id,oficina_id,ordem_servico_id,token_hash,expira_em,criado_por) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),o.oficinaId(),orderId,hash,Timestamp.from(clock.instant().plus(Duration.ofDays(7))),o.id());return new Link(token,clock.instant().plus(Duration.ofDays(7)));}catch(Exception e){throw new IllegalStateException(e);}}@DeleteMapping public void revoke(Authentication a,@PathVariable UUID orderId){Identidade o=owner(a);orders.order(o,orderId);jdbc.update("UPDATE portal_link_os SET revogado_em=now() WHERE oficina_id=? AND ordem_servico_id=? AND revogado_em IS NULL",o.oficinaId(),orderId);}@SuppressWarnings("unused") private Identidade owner(Authentication a){if(a==null||!(a.getDetails() instanceof Identidade o))throw new ApiException(401,"NAO_AUTENTICADO","Entre novamente.");return o;}public record Link(String token,Instant expiraEm){}}
